import * as fs from 'node:fs/promises';
import * as net from 'node:net';
import {createHash} from 'node:crypto';
import path from 'node:path';
import {once} from 'node:events';
import {withFileLock} from '/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js';
const base='/tmp/codex-tool-runs/svton/m2-r2-tcp-review-20261001';
const dir=await fs.mkdtemp(base+'/boundaries-');
const portFor=f=>49152+createHash('sha256').update(path.resolve(f)).digest().readUInt32BE(0)%16383;
const defer=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve}};
const pause=ms=>new Promise(r=>setTimeout(r,ms));
const guard=setTimeout(()=>{console.error('REPRO_TIMEOUT');process.exit(2)},12000);
const results={};
// Same physical state file, two names through a symlinked parent directory.
const real=dir+'/real';await fs.mkdir(real);await fs.symlink(real,dir+'/alias','dir');
const file=real+'/state.json',alias=dir+'/alias/state.json';await fs.writeFile(file,'0');
if(portFor(file)===portFor(alias))throw Error('fixture port collision; rerun with a fresh directory');
const ae=defer(),be=defer(),ra=defer(),rb=defer();let active=0,maxActive=0;
const a=withFileLock(file,async()=>{active++;maxActive=Math.max(maxActive,active);const old=Number(await fs.readFile(file,'utf8'));ae.resolve();await ra.promise;await fs.writeFile(file,String(old+1));active--;});
await ae.promise;
const b=withFileLock(alias,async()=>{active++;maxActive=Math.max(maxActive,active);const old=Number(await fs.readFile(alias,'utf8'));be.resolve();await rb.promise;await fs.writeFile(alias,String(old+1));active--;});
await be.promise;
results.alias={maxActive,activeAtObservation:active,sameRealPath:await fs.realpath(file)===await fs.realpath(alias),ports:[portFor(file),portFor(alias)]};
ra.resolve();await a;rb.resolve();await b;results.alias.finalCounter=Number(await fs.readFile(file,'utf8'));results.alias.expectedCounter=2;
// A banner visitor holds its write half open after reading server's FIN.
const held=dir+'/release.json',entered=defer(),release=defer();let settled=false;
const work=withFileLock(held,async()=>{entered.resolve();await release.promise;}).finally(()=>{settled=true});
await entered.promise;
const socket=net.connect({host:'127.0.0.1',port:portFor(held),allowHalfOpen:true});
await once(socket,'data');release.resolve();await pause(350);
results.shutdown={resolvedWhilePeerOpen:settled,observationMs:350,netServerHasCloseAllConnections:typeof net.createServer().closeAllConnections==='function'};
socket.destroy();await work;results.shutdown.resolvedAfterPeerDestroyed=settled;
// Foreign occupant accepts a connection but never sends a banner.
const silentFile=dir+'/silent.json',visitors=new Set();
const silent=net.createServer(s=>{visitors.add(s);s.on('close',()=>visitors.delete(s));});
silent.listen(portFor(silentFile),'127.0.0.1');await once(silent,'listening');
let error='';const start=Date.now();
try{await withFileLock(silentFile,()=>{}, {timeoutMs:100});}catch(e){error=e.message;}
results.silent={timeoutMs:100,elapsedMs:Date.now()-start,error};
for(const s of visitors)s.destroy();await new Promise(r=>silent.close(r));
clearTimeout(guard);await fs.writeFile(base+'/tcp-boundaries-result.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));

import net from 'node:net';
import {createHash} from 'node:crypto';
import * as fs from 'node:fs/promises';
import {once} from 'node:events';
import {withFileLock} from '/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js';
const base='/tmp/codex-tool-runs/svton/m2-r2-tcp-review-20261001';
const dir=await fs.mkdtemp(base+'/eof-'),file=dir+'/state.json';
const port=49152+createHash('sha256').update(file).digest().readUInt32BE(0)%16383;
const server=net.createServer(s=>s.end());server.listen(port,'127.0.0.1');await once(server,'listening');
let settled=false,outcome='pending';
withFileLock(file,()=>{}, {timeoutMs:100}).then(()=>{settled=true;outcome='acquired'},e=>{settled=true;outcome=e.message});
await new Promise(r=>setTimeout(r,1600));
const result={timeoutMs:100,observedMs:1600,settled,outcome,peerBehavior:'accept and immediately end without data',noMocks:true};
await new Promise(r=>server.close(r));
await fs.writeFile(base+'/probe-eof-result.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
